    "id": "price.median",
    "version": 1,
    "ref": "price.median@1",
    "class": "DEX · multi-pool price",
    "title": "Median price across pools",
    "summary": "The median price of a token in a quote token across two to four concentrated-liquidity pools of that pair, optionally refusing pools below a liquidity floor.",
    "kinds": [
      "evm",
      "svm"
    ],
    "params": [
      {
        "name": "chain",
        "type": "chain",
        "required": true,
        "doc": "CAIP-2 id or alias (EVM, Solana chains)"
      },
      {
        "name": "finality",
        "type": "finality",
        "required": false,
        "default": "final",
        "doc": "\"final\" or \"fast\", or a raw mode: \"finalized\", \"safe\", \"confirmations:<n>\" (EVM, Starknet), \"confirmed\" (Solana)"
      },
      {
        "name": "token",
        "type": "address",
        "required": true,
        "doc": "the token priced (base)"
      },
      {
        "name": "quote",
        "type": "address",
        "required": true,
        "doc": "the token it is priced in"
      },
      {
        "name": "pools",
        "type": "addressList",
        "required": true,
        "doc": "2 to 4 Uniswap v3-style pools, or Solana Orca Whirlpool and Raydium CLMM pools (mixed), of exactly this pair"
      },
      {
        "name": "minLiquidity",
        "type": "uint",
        "required": false,
        "doc": "every pool's active liquidity (raw units) must be at least this, or the round fails; on EVM at most 2 pools then (liquidity is a second read)"
      }
    ],
    "returns": "quote-token units per one token, 18 decimals (uint256; int256 on Solana, tolerance mode)",
    "caveats": [
      "The median is taken over the pools' square-root prices, then squared: for an even count it is the square of the mean of the two middle square roots, a hair below the mean of the two middle prices.",
      "A pool below the floor fails the whole round; nothing is signed without it.",
      "No USD: the price names its quote token."
    ],
    "example": {
      "chain": "ethereum",
      "pools": "0x88e6a0c2ddd26feeb64f039a2c41296fcb3f5640,0x8ad599c3a0ff1de082011efddc58f1908eb6e6d8,0xe0554a476a092703abdb3ef35c80e0d76d32939f",
      "quote": "0xa0b86991c6218b36c1d19d4a2e9eb0ce3606eb48",
      "token": "0xc02aaa39b223fe8d0a0e5c4f27ead9083c756cc2"
    },
